  str_homestory_N23dianying_90030101_165_dialog_content = "Eu não sei... eu não sei quem ou o que ele deveria ser!",
  str_homestory_N23dianying_90030101_166_dialog_content = "Ei! A luz acende e apaga novamente! A porta ainda está travada?",
