  str_homestory_N23dianying_90030101_176_dialog_content = "O Conquistador do Terror e do Medo.",
  str_homestory_N23dianying_90030101_177_dialog_content = "O Filho do Vazio e do Caos.",
  str_homestory_N23dianying_90030101_178_dialog_content = "Johnny, o Grande Lorde Demônio Culinário!",
  str_homestory_N23dianying_90030101_179_dialog_content = "Eu sacrifico a você os mais deliciosos e frescos vermes da areia!",
  str_homestory_N23dianying_90030101_180_dialog_content = "Seu servo espera por você!",
  str_homestory_N23dianying_90030101_181_dialog_content = "...",
  str_homestory_N23dianying_90030101_182_dialog_content = "...",
  str_homestory_N23dianying_90030101_183_dialog_content = "Isso não é da minha conta...",
  str_homestory_N23dianying_90030101_184_dialog_content = "Diretor! Há algo obviamente errado com os adereços!",
  str_homestory_N23dianying_90030101_185_dialog_content = "Temos muito espaço para melhorias em termos de adereços, você não acha? Chubb.",
  str_homestory_N23dianying_90030101_186_dialog_content = "Huh? Encontrar o quê? O que você está falando?",
  str_homestory_N23dianying_90030101_187_dialog_content = "Encontre... Vá encontrar a verdade...",
  str_homestory_N23dianying_90030101_188_dialog_content = "Eu não acabei de te dizer? Encontre-o... Vá encontrar a verdade!",
  str_homestory_N23dianying_90030101_189_dialog_content = "Mas não há nada nesse sentido!",
  str_homestory_N23dianying_90030101_190_dialog_content = "Não? Como isso é possível?",
  str_homestory_N23dianying_90030101_191_dialog_content = "Você não pode vê-lo? É onde a carne foi dilacerada e a alma devorada.",
  str_homestory_N23dianying_90030101_192_dialog_content = "O lugar onde coloquei minhas cópias manuscritas do dogma.",
  str_homestory_N23dianying_90030101_193_dialog_content = "Acho que tem alguma coisa errada com os adereços...",
  str_homestory_N23dianying_90030101_194_dialog_content = "E, Nails, você não estava seguindo suas falas!",
  str_homestory_N23dianying_90030101_195_dialog_content = "Sinto muito... vou me desculpar e confessar com unhas...",
  str_homestory_N23dianying_90030101_196_dialog_content = "Para para para! Este não é um filme de terror sangrento! Vai bagunçar o conjunto também!",
  str_homestory_N23dianying_90030101_197_dialog_content = "É tão difícil imaginar...",
  str_homestory_N23dianying_90030101_198_dialog_content = "Coloque uma tampa nele, sim? Pare de trazer vergonha ao nome da Verdadeira Ordem!",
  str_homestory_N23dianying_90030101_199_dialog_content = "Você realmente não pode ver isso? A equipe de adereços realmente deixou a bola cair!",
  str_homestory_N23dianying_90030101_200_dialog_content = "Atuar com adereços imaginários é tão pouco confiável!",
  str_homestory_N23dianying_90030101_201_dialog_content = "Todos os adereços e conjuntos parecem baratos. Isso não é maneira de fazer um filme de qualidade!",
  str_homestory_N23dianying_90030101_202_dialog_content = "Bem, você tem um ponto.",
  str_homestory_N23dianying_90030101_203_dialog_content = "Definitivamente há algo errado, especialmente quando até Brock pensa assim.",
  str_homestory_N23dianying_90030101_204_dialog_content = "Ei! O que isso quer dizer!?",
  str_homestory_N23dianying_90030101_205_dialog_content = "De qualquer forma, é melhor prepararmos os adereços e refazermos isso.",
  str_homestory_N23dianying_90030101_206_dialog_content = "Está tudo bem. Como protagonista feminina, sou paciente. Voltaremos assim que o set estiver preparado.",
  str_homestory_N23dianying_90030201_1_dialog_content = "Esta é a parte mais profunda da lendária Caverna do Dragão - o Salão dos Tesouros...?",
  str_homestory_N23dianying_90030201_2_dialog_content = "Bem, este deve ser o lendário Frost Mirror! Ele pode responder a qualquer pergunta que você fizer, e tem um poder mágico inesgotável!",
  str_homestory_N23dianying_90030201_2X1_dialog_content = "Bem, o lendário Frost Mirror tem que estar aqui! Ele pode responder a qualquer pergunta que você fizer, e tem um poder mágico inesgotável!",
  str_homestory_N23dianying_90030201_3_dialog_content = "Eu não tenho ideia de onde aquele dragão protetor de espelho estúpido foi, mas conseguir isso foi um pedaço de bolo.",
  str_homestory_N23dianying_90030201_3X1_dialog_content = "Eu não tenho ideia de onde aquele dragão protetor de espelho estúpido foi, mas entrar aqui foi muito fácil.",
  str_homestory_N23dianying_90030201_4_dialog_content = "Contanto que realmente tiremos isso daqui... Haverá um monte de gente implorando para pagar caro por isso. Quem sabe, o rei pode até me conceder um título e algumas terras!",
  str_homestory_N23dianying_90030201_4X1_dialog_content = "Ou eu poderia simplesmente usar seu poder para ganhar muito dinheiro! Eu entraria na lista dos ricos em nenhum momento!",
  str_homestory_N23dianying_90030201_5_dialog_content = "Hahaha... Um tesouro tão raro está finalmente nas mãos de Barbatos, o maior comerciante criminoso de todos os tempos!",
  str_homestory_N23dianying_90030201_6_dialog_content = "E-Então... Ahem, então eu vou me ajudar.",
  str_homestory_N23dianying_90030201_6X1_dialog_content = "Como eles poderiam ter suas falas erradas? Chubb.",
  str_homestory_N23dianying_90030201_6X2_dialog_content = "Você consegue, Revy!",
  str_homestory_N23dianying_90030201_6X3_dialog_content = "O pagamento deles deve ser reduzido por dizer a coisa errada, certo? Chubb.",
  str_homestory_N23dianying_90030201_7_dialog_content = "Oh? Alguém se aproxima. Mas como eles estão no Salão dos Tesouros...?",
  str_homestory_N23dianying_90030201_7X1_dialog_content = "O que? Juro que procurei em todos os lugares, mas não há nada que se pareça com um espelho mágico.",
  str_homestory_N23dianying_90030201_8_dialog_content = "Ah, esqueça, não há tempo para isso. Vou me esconder atrás do espelho primeiro.",
  str_homestory_N23dianying_90030201_8X1_dialog_content = "Certamente ninguém mais poderia ter roubado o espelho...?",
  str_homestory_N23dianying_90030201_9_dialog_content = "Encontrei! Eu encontrei-!!",
  str_homestory_N23dianying_90030201_9X1_dialog_content = "Encontrei! Eu encontrei-!! Esta deve ser a fase final!",
  str_homestory_N23dianying_90030201_10_dialog_content = "Deixe-me dar uma olhada. Hm... Esta linda árvore cintilante...",
  str_homestory_N23dianying_90030201_10X1_dialog_content = "Deixe-me dar uma olhada nesta linda árvore cintilante!",
  str_homestory_N23dianying_90030201_11_dialog_content = "Hmm... Uma estátua tão vã do Dragão de Gelo.",
  str_homestory_N23dianying_90030201_11X1_dialog_content = "Há também esta impressionante estátua do Frost Dragon!",
  str_homestory_N23dianying_90030201_14_dialog_content = "Excelente! Deu muito trabalho, mas finalmente vencemos o Frost Dragon e chegamos aqui!",
  str_homestory_N23dianying_90030201_14X1_dialog_content = "Excelente! Deu muito trabalho, mas finalmente vencemos o Frost Dragon e chegamos aqui! Então, onde está a recompensa suprema?",
  str_homestory_N23dianying_90030201_16_dialog_content = "Huh...? É uma boneca de urso? Dragões de Gelo também gostam desse tipo de coisa?",
  str_homestory_N23dianying_90030201_16X1_dialog_content = "O que é isso? Uma boneca de urso? Ahaha! Os Dragões de Gelo também gostam desse tipo de coisa?",
  str_homestory_N23dianying_90030201_17_dialog_content = "Eu realmente não consigo ver...",
  str_homestory_N23dianying_90030201_17X1_dialog_content = "Eu simplesmente não consigo ver!",
  str_homestory_N23dianying_90030201_18_dialog_content = "Parece basicamente se encaixar com os rumores.",
  str_homestory_N23dianying_90030201_18X1_dialog_content = "Basicamente de acordo com os rumores.",
  str_homestory_N23dianying_90030201_19_dialog_content = "Este lugar deveria ser o Hall of Treasures, guardado pelo Frost Dragon.",
  str_homestory_N23dianying_90030201_19X1_dialog_content = "Este lugar deveria ser o Salão dos Tesouros, guardado pelo Dragão de Gelo!",
  str_homestory_N23dianying_90030201_22_dialog_content = "Oh? O que é isso...? Parece meio fora do lugar.",
  str_homestory_N23dianying_90030201_22X1_dialog_content = "Oh? O que é isso? Parece totalmente fora do lugar.",
  str_homestory_N23dianying_90030201_23_dialog_content = "Embora se diga que os dragões também colecionam algumas coisas estranhas, então acho que é compreensível.",
  str_homestory_N23dianying_90030201_23X1_dialog_content = "Bem, parece que os Frost Dragons não são tão brilhantes. Talvez tenha sido mal colocado.",
  str_homestory_N23dianying_90030201_27_dialog_content = "Deixe-me ver... Hum, isso não é um cabideiro?",
  str_homestory_N23dianying_90030201_27X1_dialog_content = "Deixe-me ver. Huh? Isso é um cabideiro?",
  str_homestory_N23dianying_90030201_28_dialog_content = "E se você olhar para as roupas nele, elas não parecem ser o tipo de coisa que um personagem de um conto de fadas pode usar?",
  str_homestory_N23dianying_90030201_28X1_dialog_content = "E como há roupas de meninas nele? Será que o Frost Dragon pode se transformar em uma garota?",
  str_homestory_N23dianying_90030201_37_dialog_content = "Este é realmente o Salão dos Tesouros?",
  str_homestory_N23dianying_90030201_37X1_dialog_content = "Este é realmente o Salão dos Tesouros? Não erramos?",
  str_homestory_N23dianying_90030201_38_dialog_content = "Claro que é! Não passamos por todo esse problema E vencemos o Frost Dragon para chegar aqui?!",
  str_homestory_N23dianying_90030201_38X1_dialog_content = "Claro que é! Não passamos por todo esse problema E vencemos o Frost Dragon para chegar aqui?! Além disso, o passo a passo disse que estava aqui também!",
  str_homestory_N23dianying_90030201_45_dialog_content = "Deixe-me ver. Hmmm, há um boneco de neve adorável?!",
  str_homestory_N23dianying_90030201_45X1_dialog_content = "Deixe-me ver. Huh? Como é que há um boneco de neve? Me lembra de fazer um com meus camaradas.",
  str_homestory_N23dianying_90030201_46_dialog_content = "Não parece que vai derreter. O Frost Dragon fez isso com seu próprio poder?",
  str_homestory_N23dianying_90030201_46X1_dialog_content = "Não parece que vai derreter. Bastante impressionante.",
  str_homestory_N23dianying_90030201_63_dialog_content = "(O-o que...?! Esses caras realmente conseguiram derrotar o Frost Dragon? Aquele que disse ser capaz de derrotar um exército inteiro em um piscar de olhos?)",
  str_homestory_N23dianying_90030201_63X1_dialog_content = "Huh?! Que incrível?",
  str_homestory_N23dianying_90030201_63X2_dialog_content = "Isso é uma coisa poderosa, Chubb.",
  str_homestory_N23dianying_90030201_63X3_dialog_content = "Não acredito, Chubb.",
  str_homestory_N23dianying_90030201_64_dialog_content = "(Devo me mostrar...? Talvez se eu explicar que sou apenas um ladrão ou um comerciante ou algo assim, isso os impeça de pensar que sou um inimigo se for descoberto...)",
  str_homestory_N23dianying_90030201_65_dialog_content = "Seria terrível se eles me confundissem com um monstro e fossem atrás de mim...",
  str_homestory_N23dianying_90030201_66_dialog_content = "Não precisava ser tão difícil.",
  str_homestory_N23dianying_90030201_67_dialog_content = "Isso ocorre porque você confiou cegamente em alguém que conheceu no labirinto.",
  str_homestory_N23dianying_90030201_68_dialog_content = "Aquele mercador disse que encontrou um monte de equipamentos raros na masmorra, e você simplesmente corre para negociar com ele. Mas é tudo falso!",
  str_homestory_N23dianying_90030201_69_dialog_content = "Aquele episódio nos colocou em uma posição financeira muito difícil.",
  str_homestory_N23dianying_90030201_69X1_dialog_content = "Aquele episódio nos colocou em uma posição financeira muito difícil!",
  str_homestory_N23dianying_90030201_70_dialog_content = "E agora todos estão trabalhando. Até a Srta. Curadora está ajudando os feridos a trazer algum dinheiro.",
  str_homestory_N23dianying_90030201_71_dialog_content = "Huh? Ah, não se preocupe comigo! Estou feliz em tratar os ferimentos dos outros.",
  str_homestory_N23dianying_90030201_72_dialog_content = "Umm, uh... Isso foi apenas um lapso momentâneo de julgamento. Eu tenho sido muito mais cuidadoso desde então!",
  str_homestory_N23dianying_90030201_72X1_dialog_content = "Umm, uh... Isso foi apenas um lapso momentâneo de julgamento.",
  str_homestory_N23dianying_90030201_72X2_dialog_content = "Eu não esperava que um NPC de aparência inofensiva fosse uma ameaça.",
  str_homestory_N23dianying_90030201_73_dialog_content = "Isso não é realmente ser mais cuidadoso... E depois disso veio o ladrão, que alegou ser capaz de nos ajudar a desarmar as armadilhas na masmorra.",
  str_homestory_N23dianying_90030201_73X1_dialog_content = "Oh sério? Depois veio o ladrão, que afirmou ser capaz de nos ajudar a desarmar as armadilhas da masmorra.",
  str_homestory_N23dianying_90030201_74_dialog_content = "Mas você o deixou se juntar a nós porque você odeia lidar com armadilhas, apenas para acordar com todos os equipamentos desaparecidos?!",
  str_homestory_N23dianying_90030201_74X1_dialog_content = "Você o deixou se juntar a nós porque odeia lidar com armadilhas, apenas para acordar com todos os equipamentos desaparecidos!",
  str_homestory_N23dianying_90030201_75_dialog_content = "Felizmente, era tudo equipamento normal. O equipamento avançado estava no ferreiro para reparos.",
  str_homestory_N23dianying_90030201_76_dialog_content = "Caso contrário, seria uma verdadeira dor de cabeça ter que começar de novo do nada.",
  str_homestory_N23dianying_90030201_77_dialog_content = "Eu já sei! Eu não vou ser tão ingênuo novamente!",
  str_homestory_N23dianying_90030201_77X1_dialog_content = "Eu já sei! Uma vez mordido, duas vezes tímido!",
  str_homestory_N23dianying_90030201_78_dialog_content = "Se eu encontrar alguém alegando ser um ladrão, ou um homem de negócios, ou basicamente alguém suspeito, eu vou dar-lhes um golpe ali mesmo. Poupe-me algum aborrecimento.",
  str_homestory_N23dianying_90030201_79_dialog_content = "Mmhmm, isso é mais parecido com isso.",
  str_homestory_N23dianying_90030201_80_dialog_content = "(... Isso soa fatal se eu me mostrar. Melhor ficar escondido.)",
  str_homestory_N23dianying_90030201_81_dialog_content = "Vamos ver como usar o espelho mágico primeiro. Parece que me lembro da lenda dizendo que o espelho poderia responder a qualquer pergunta?",
  str_homestory_N23dianying_90030201_82_dialog_content = "Parece um espelho comum para mim.",
  str_homestory_N23dianying_90030201_82X1_dialog_content = "Parece um espelho comum para mim. Você acha que há um interruptor ou algo assim?",
  str_homestory_N23dianying_90030201_83_dialog_content = "Bem, bater não fez nada. Vocês têm alguma ideia?",
  str_homestory_N23dianying_90030201_83X1_dialog_content = "Encontramos algum fragmento de diário com informações relevantes no caminho? O que vocês estão pensando?",
  str_homestory_N23dianying_90030201_84_dialog_content = "Nada! Estou interessado apenas em tiro com arco.",
  str_homestory_N23dianying_90030201_84X1_dialog_content = "Nada! Estou interessado apenas em tiro com arco e jogos de guerra.",
  str_homestory_N23dianying_90030201_85_dialog_content = "Nada aqui também. Estou interessado apenas em medidas terapêuticas. Outras magias me confundem.",
  str_homestory_N23dianying_90030201_85X1_dialog_content = "Nada aqui também. Só estou interessado em mel... Quero dizer, os usos terapêuticos do mel.",
  str_homestory_N23dianying_90030201_86_dialog_content = "Não é uma coincidência! Acontece que eu só estava interessado em cortar e cortar monstros, mas agora, meu interesse se expandiu para incluir o corte e corte de estranhos suspeitos.",
  str_homestory_N23dianying_90030201_87_dialog_content = "(Huh? Nenhum deles estuda magia?)",
  str_homestory_N23dianying_90030201_88_dialog_content = "(Essa pode ser minha chance...)",
  str_homestory_N23dianying_90030201_89_dialog_content = "Huh?! Alguém está se escondendo atrás do espelho mágico?",
  str_homestory_N23dianying_90030201_89X1_dialog_content = "Huh?! Tem alguém por trás do espelho mágico? Um inimigo oculto?",
  str_homestory_N23dianying_90030201_90_dialog_content = "Bem-vindos todos!",
  str_homestory_N23dianying_90030201_91_dialog_content = "Bravos exploradores.",
  str_homestory_N23dianying_90030201_92_dialog_content = "Q-Quem é você? O que você está fazendo aqui?",
  str_homestory_N23dianying_90030201_92X1_dialog_content = "Q-Quem é você? O que você está fazendo aqui? Você é um inimigo ou algum tipo de ovo de páscoa?",
  str_homestory_N23dianying_90030201_93_dialog_content = "Não há necessidade de temer.",
  str_homestory_N23dianying_90030201_94_dialog_content = "Não precisa se preocupar.",
  str_homestory_N23dianying_90030201_95_dialog_content = "Eu sou o espírito que reside dentro deste objeto, o Gênio do Espelho.",
  str_homestory_N23dianying_90030201_95X1_dialog_content = "Ela está entrando nisso! Hahaha!",
  str_homestory_N23dianying_90030201_95X2_dialog_content = "Isso é embaraçoso, Chubb!",
  str_homestory_N23dianying_90030201_95X3_dialog_content = "Eles estão realmente imersos em seu personagem, Chubb.",
  str_homestory_N23dianying_90030201_96_dialog_content = "Gênio do Espelho...? Acho que não ouvi você mencionado em nenhuma das lendas.",
  str_homestory_N23dianying_90030201_97_dialog_content = "Muito certo, muito certo. Mas as lendas são apenas isso, afinal. Não é como se alguém tivesse realmente recuperado o Frost Mirror, não é?",
  str_homestory_N23dianying_90030201_97X1_dialog_content = "Muito certo, muito certo. Mas as lendas são apenas isso, afinal. Não é como se alguém tivesse realmente recuperado o Frost Mirror.",
  str_homestory_N23dianying_90030201_98_dialog_content = "Mas por que está falando de uma maneira tão engraçada?",
  str_homestory_N23dianying_90030201_98X1_dialog_content = "O tom desse cara é suspeito, se você me perguntar.",
  str_homestory_N23dianying_90030201_99_dialog_content = "Isso é, ah, isso é porque eu estou selado aqui há muito tempo, com poder mágico insuficiente.",
  str_homestory_N23dianying_90030201_100_dialog_content = "Eu imploro, me leve para longe daqui, para longe do Dragão de Gelo! Leve-me para uma terra distante e desabitada.",
  str_homestory_N23dianying_90030201_101_dialog_content = "(Depois do que eu vou escapar na noite com meu espelho mágico. Heehee...)",
  str_homestory_N23dianying_90030201_102_dialog_content = "Oh, eu vejo! Bem, é melhor irmos!",
  str_homestory_N23dianying_90030201_103_dialog_content = "Aguarde um minuto! E aquele negócio de \"confiar nos outros com muita facilidade\"? Pelo menos peça a opinião da Srta. Curadora primeiro!",
  str_homestory_N23dianying_90030201_104_dialog_content = "Um verdadeiro Gênio deve ser capaz de nos dar uma pequena demonstração do poder do espelho. Isso seria suficiente para provar suas alegações.",
  str_homestory_N23dianying_90030201_104X1_dialog_content = "Deixe-me pensar... Ah!",
  str_homestory_N23dianying_90030201_104X2_dialog_content = "Ahn? O que é?",
  str_homestory_N23dianying_90030201_104X3_dialog_content = "O tempo escapou de mim - eu tive que terminar uma missão que a rainha me deu! Sinto muito, Diretor!",
  str_homestory_N23dianying_90030201_104X4_dialog_content = "Ei, é o que é. Encontraremos um substituto.",
  str_homestory_N23dianying_90030201_105_dialog_content = "(... Isso era de se esperar. No entanto, estou preparado.)",
  str_homestory_N23dianying_90030201_106_dialog_content = "Mas é claro.",
  str_homestory_N23dianying_90030201_107_dialog_content = "Por favor, observe—",
  str_homestory_N23dianying_90030201_108_dialog_content = "Que haja luz!",
  str_homestory_N23dianying_90030201_109_dialog_content = "Espelho mágico.",
  str_homestory_N23dianying_90030201_110_dialog_content = "(Esses pergaminhos mágicos caros são úteis.)",
  str_homestory_N23dianying_90030201_111_dialog_content = "Uau! Na verdade está respondendo!",
  str_homestory_N23dianying_90030201_112_dialog_content = "Com certeza, você não pode simplesmente baloiçar como um \"Herói\". Parece precisar do Gênio do Espelho para funcionar.",
  str_homestory_N23dianying_90030201_112X1_dialog_content = "Com certeza, adivinhação heróica selvagem não vai funcionar. Parece que precisamos da ajuda do Gênio do Espelho para usá-lo.",
  str_homestory_N23dianying_90030201_113_dialog_content = "Ohhh... Aposto que vai funcionar com mais algumas boas palmadas!",
  str_homestory_N23dianying_90030201_113X1_dialog_content = "Ohhh... Aposto que vai funcionar com mais algumas boas palmadas! Muitos jogos têm esse design!",
  str_homestory_N23dianying_90030201_114_dialog_content = "Não tenho certeza se posso tratar um Espelho Mágico quebrado...",
  str_homestory_N23dianying_90030201_115_dialog_content = "Não importa isso por enquanto! Vá em frente e experimente suas habilidades de resposta a perguntas!",
  str_homestory_N23dianying_90030201_116_dialog_content = "Dê um passo à frente, Srta. Curandeira!",
  str_homestory_N23dianying_90030201_117_dialog_content = "Ok! Oh, Espelho Mágico, Espelho Mágico... Qual será o ápice das minhas realizações de cura?",
  str_homestory_N23dianying_90030201_118_dialog_content = "Essa é a maneira de perguntar, certo?",
  str_homestory_N23dianying_90030201_119_dialog_content = "Um momento-",
  str_homestory_N23dianying_90030201_120_dialog_content = "A resposta está surgindo.",
  str_homestory_N23dianying_90030201_121_dialog_content = "Você ganhará fama e fortuna tratando de um laird, que caiu em um sono por causa de sua doença.",
  str_homestory_N23dianying_90030201_122_dialog_content = "Mas seu maior e último feito será curar o Rei Demônio da narcolepsia e dotá-lo de energia infinita.",
  str_homestory_N23dianying_90030201_123_dialog_content = "Isso tem o infeliz efeito colateral de fazê-lo permanecer eternamente acordado e, em sua raiva e excesso de poder, ele destrói o mundo inteiro.",
  str_homestory_N23dianying_90030201_123X1_dialog_content = "Vá em frente, continue inventando coisas.",
  str_homestory_N23dianying_90030201_123X2_dialog_content = "Estão improvisando? Chubb.",
  str_homestory_N23dianying_90030201_123X3_dialog_content = "Ninguém vai acreditar nisso, Chubb!",
  str_homestory_N23dianying_90030201_124_dialog_content = "...",
  str_homestory_N23dianying_90030201_125_dialog_content = "T-O Espelho Mágico nem sempre é totalmente preciso, certo? Não há necessidade de acreditar em cada palavra.",
  str_homestory_N23dianying_90030201_126_dialog_content = "Na verdade, eu sou poderoso o suficiente para despertar o Rei Demônio??",
  str_homestory_N23dianying_90030201_127_dialog_content = "Hehehe...",
  str_homestory_N23dianying_90030201_128_dialog_content = "Não é engraçado, Srta. Curandeira! Você está me enlouquecendo.",
  str_homestory_N23dianying_90030201_129_dialog_content = "Não se preocupe comigo! A vez do arqueiro!",
  str_homestory_N23dianying_90030201_130_dialog_content = "Meh, eu não estou incomodado. Eu nem estou interessado em todas essas coisas.",
  str_homestory_N23dianying_90030201_131_dialog_content = "Deixe o herói ir em seguida.",
  str_homestory_N23dianying_90030201_132_dialog_content = "Claro! Espelho Mágico, Espelho Mágico, diga-me agora o quão poderoso eu serei!",
  str_homestory_N23dianying_90030201_133_dialog_content = "Você... Você abandonará seu título de Herói da Luz e se apaixonará pelas pequenas criaturas que encontrar em suas aventuras.",
  str_homestory_N23dianying_90030201_133X1_dialog_content = "Você... Você abandonará seu título de Herói da Luz e começará a estudar \"Magimechs\", um tipo de robô gigante.",
  str_homestory_N23dianying_90030201_134_dialog_content = "Você trabalhará com eles para derrubar todos os seus inimigos Gym Leader, um por um.",
  str_homestory_N23dianying_90030201_134X1_dialog_content = "Mas esses robôs, inicialmente criados para proteger as pessoas, tornam-se autoconscientes e começam a atacar as pessoas.",
  str_homestory_N23dianying_90030201_135_dialog_content = "Mas você... nunca se tornará Campeão, e eventualmente perecerá em ignomínia desanimada.",
  str_homestory_N23dianying_90030201_135X1_dialog_content = "E você embarcará em uma missão com seu único amigo robô, para descobrir a verdade por trás da insurreição de Magimech.",
  str_homestory_N23dianying_90030201_135A1_dialog_content = "Está ficando cada vez mais ridículo, Chubb.",
  str_homestory_N23dianying_90030201_135A2_dialog_content = "Isso soa familiar?",
  str_homestory_N23dianying_90030201_135A3_dialog_content = "É inexplicavelmente atraente?",
  str_homestory_N23dianying_90030201_136_dialog_content = "Quais são as chances...",
  str_homestory_N23dianying_90030201_137_dialog_content = "Seu Espelho Mágico sem sentido! Como você se atreve a caluniar meu amado Herói!",
  str_homestory_N23dianying_90030201_137X1_dialog_content = "Você continua falando bobagens, Espelho! Como você se atreve a caluniar nosso poderoso Herói!",
  str_homestory_N23dianying_90030201_138_dialog_content = "Huh? Espere! Aguarde um minuto!",
  str_homestory_N23dianying_90030201_139_dialog_content = "Então ESSA É a sua relação—!",
  str_homestory_N23dianying_90030201_139X1_dialog_content = "Relaxar!",
  str_homestory_N23dianying_90030201_140_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  str_homestory_N23dianying_90030201_141_dialog_content = "Ei, o que você está fazendo? Se você danificar o Espelho Mágico, o Gênio pode ser ferido, ou até mesmo morto!",
  str_homestory_N23dianying_90030201_142_dialog_content = "Olhe para sua expressão de dor!",
  str_homestory_N23dianying_90030201_143_dialog_content = "Dolorido... expressão?",
  str_homestory_N23dianying_90030201_144_option_content = "Colapso",
  str_homestory_N23dianying_90030201_145_dialog_content = "Cai, Barbatos! \"Faça um barulho de dor e desmaie!\"",
  str_homestory_N23dianying_90030201_146_dialog_content = "Ahhh...",
  str_homestory_N23dianying_90030201_147_dialog_content = "... Oh! Que agonia!",
  str_homestory_N23dianying_90030201_148_dialog_content = "Eu estou ferido-",
  str_homestory_N23dianying_90030201_149_dialog_content = "Desculpe... fui muito impulsivo...",
  str_homestory_N23dianying_90030201_149X1_dialog_content = "Sinto muito... Estas são as loucuras da juventude.",
  str_homestory_N23dianying_90030201_150_dialog_content = "Posso incomodá-la para tentar, Srta. Curandeira?",
  str_homestory_N23dianying_90030201_151_dialog_content = "Vou tentar... Nem que seja para mexer um pouco a panela! Afinal, sou eu quem pode tratar um rei demônio!",
  str_homestory_N23dianying_90030201_152_dialog_content = "Você não vai deixar ninguém esquecer isso tão cedo, vai?",
  str_homestory_N23dianying_90030201_153_dialog_content = "Hmm, claramente é o Espelho Mágico, mas como é que se danifica tão facilmente?",
  str_homestory_N23dianying_90030201_154_dialog_content = "Artesanato de má qualidade.",
  str_homestory_N23dianying_90030201_155_dialog_content = "Eu sinto poder de cura.",
  str_homestory_N23dianying_90030201_156_dialog_content = "Eu, o Gênio do Espelho, estou restaurado!",
  str_homestory_N23dianying_90030201_157_dialog_content = "Excelente! E, uh, nossas desculpas.",
  str_homestory_N23dianying_90030201_157X1_dialog_content = "Excelente! E, uh, desculpe por isso.",
  str_homestory_N23dianying_90030201_158_dialog_content = "Às vezes o Arqueiro é ainda mais impetuoso do que eu. Mas tirando essa pequena falha, ela tem um bom coração.",
  str_homestory_N23dianying_90030201_159_dialog_content = "Desde quando vocês dois...",
  str_homestory_N23dianying_90030201_160_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_161_dialog_content = "Isso vem de fora?!",
  str_homestory_N23dianying_90030201_162_dialog_content = "É o Dragão de Gelo!",
  str_homestory_N23dianying_90030201_163_dialog_content = "Imbecis! Você realmente achou que poderia me matar?",
  str_homestory_N23dianying_90030201_164_dialog_content = "Você perdeu sua chance de me derrotar, e agora estou indo embora... e levando o Espelho de Gelo comigo!",
  str_homestory_N23dianying_90030201_165_dialog_content = "Lamentar sua estupidez para o resto de suas vidas! Hahahaha—",
  str_homestory_N23dianying_90030201_166_dialog_content = "...",
  str_homestory_N23dianying_90030201_167_dialog_content = "...",
  str_homestory_N23dianying_90030201_168_dialog_content = "...",
  str_homestory_N23dianying_90030201_169_dialog_content = "O que aquele dragão idiota estava dizendo??",
  str_homestory_N23dianying_90030201_170_dialog_content = "Não percebeu que agora temos o Frost Mirror.",
  str_homestory_N23dianying_90030201_170X1_dialog_content = "Que grande palhaço! NÓS temos o Frost Mirror, hahaha!",
  str_homestory_N23dianying_90030201_171_dialog_content = "Mas agora que sabemos que o Dragão de Gelo está atrás do Espelho, temos que estar em guarda e ficar de olho nele o tempo todo.",
  str_homestory_N23dianying_90030201_172_dialog_content = "Não se preocupe. Nós vamos protegê-lo.",
  str_homestory_N23dianying_90030201_173_dialog_content = "... Sim Sim. Multar. Você está totalmente certo.",
  str_homestory_N23dianying_90030201_174_dialog_content = "Realmente, sou muito grato a você.",
  str_homestory_N23dianying_90030201_175_option_content = "Sentir que algo não está certo",
  str_homestory_N23dianying_90030201_176_dialog_content = "Archer, de repente você sente que algo está errado. \"Esse cara é realmente suspeito.\"",
  str_homestory_N23dianying_90030201_177_dialog_content = "Mesmo que o espelho, onde você supostamente mora, tenha sido claramente atacado, você não pareceu reagir. Não é estranho?",
  str_homestory_N23dianying_90030201_177X1_dialog_content = "Mesmo que o espelho, onde você supostamente mora, tenha sido claramente atacado, você não pareceu reagir. Isso é realmente muito estranho.",
  str_homestory_N23dianying_90030201_178_dialog_content = "O que? Você está dizendo que esse cara...",
  str_homestory_N23dianying_90030201_178X1_dialog_content = "O que? Você quer dizer... você está dizendo que esse cara não é nenhum tipo de ovo de páscoa?",
  str_homestory_N23dianying_90030201_179_dialog_content = "Espere, espere um minuto! Posso explicar — estou com dor, tanta dor que acho que vou desmaiar!",
  str_homestory_N23dianying_90030201_180_dialog_content = "Eu posso explicar! Por favor, apenas ouça.",
  str_homestory_N23dianying_90030201_181_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_182_dialog_content = "Isso vem de fora?!",
  str_homestory_N23dianying_90030201_183_dialog_content = "É o Dragão de Gelo!",
  str_homestory_N23dianying_90030201_184_dialog_content = "Imbecis! Você realmente achou que poderia me matar?",
  str_homestory_N23dianying_90030201_185_dialog_content = "Você perdeu sua chance de me derrotar, e agora estou indo embora... e levando o Espelho de Gelo comigo!",
  str_homestory_N23dianying_90030201_186_dialog_content = "Lamentar sua estupidez para o resto de suas vidas! Hahahaha—",
  str_homestory_N23dianying_90030201_187_dialog_content = "Sem perdão—",
  str_homestory_N23dianying_90030201_188_option_content = "Realização repentina",
  str_homestory_N23dianying_90030201_189_dialog_content = "Herói, de repente você percebe algo vital. \"A espada se foi.\"",
  str_homestory_N23dianying_90030201_190_dialog_content = "Espere, esqueça isso por um segundo. É impressão minha ou está faltando a espada?",
  str_homestory_N23dianying_90030201_191_dialog_content = "De jeito nenhum... Ele ainda não pode estar preso na cabeça do Dragão de Gelo, pode?",
  str_homestory_N23dianying_90030201_192_dialog_content = "Rápido, vamos voltar e procurá-lo! Estamos em apuros se Hero perder a espada!",
  str_homestory_N23dianying_90030201_193_dialog_content = "Oh? Erm... Vem de novo?",
  str_homestory_N23dianying_90030201_194_dialog_content = "Huh? Quem é?",
  str_homestory_N23dianying_90030201_194X1_dialog_content = "Huh? Quem é? Um NPC de fundo?",
  str_homestory_N23dianying_90030201_195_dialog_content = "Esqueça ela. Precisamos olhar para o espelho.",
  str_homestory_N23dianying_90030201_195X1_dialog_content = "Esqueça ela. Precisamos olhar para o espelho. Ainda tenho coisas que preciso fazer depois.",
  str_homestory_N23dianying_90030201_196_dialog_content = "Hum?",
  str_homestory_N23dianying_90030201_197_dialog_content = "O quê?",
  str_homestory_N23dianying_90030201_198_dialog_content = "Como é que não há sinal do Espelho Mágico?",
  str_homestory_N23dianying_90030201_198X1_dialog_content = "Como é que não há sinal do Espelho Mágico? Ainda não marcamos alguma caixa arbitrária??",
  str_homestory_N23dianying_90030201_199_dialog_content = "Você acha que esse cara roubou?",
  str_homestory_N23dianying_90030201_200_dialog_content = "O que?! Eu estava prestes a te perguntar isso.",
  str_homestory_N23dianying_90030201_201_dialog_content = "Não foi divertido me infiltrar aqui, e eu tive que ter aquele espelho para me tornar o mercador mais rico do mundo.",
  str_homestory_N23dianying_90030201_202_dialog_content = "Esgueirando-se? Você não acha... esse cara é algum tipo de ladrão?",
  str_homestory_N23dianying_90030201_203_dialog_content = "Isso é realmente muito instigante.",
  str_homestory_N23dianying_90030201_203X1_dialog_content = "Isso traz de volta algumas memórias realmente desagradáveis. Tenho que te ensinar uma lição.",
  str_homestory_N23dianying_90030201_204_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_205_dialog_content = "Isso vem de fora?!",
  str_homestory_N23dianying_90030201_206_dialog_content = "É o Dragão de Gelo!",
  str_homestory_N23dianying_90030201_207_dialog_content = "Imbecis! Você realmente achou que poderia me derrotar?",
  str_homestory_N23dianying_90030201_208_dialog_content = "Agora, estou indo embora e levando o Espelho de Gelo comigo! Outra coisa... Este lugar vai desmoronar a qualquer momento, então lamentem sua estupidez pelo resto de suas curtas vidas! Hahahaha—",
  str_homestory_N23dianying_90030201_209_dialog_content = "Droga, o dragão escapou.",
  str_homestory_N23dianying_90030201_210_dialog_content = "Vá atrás disso, agora!",
  str_homestory_N23dianying_90030201_210X1_dialog_content = "Apressem-se, todos! Eu, uh, vou terminar uma missão que a rainha me deu!",
  str_homestory_N23dianying_90030201_211_dialog_content = "Uh? Ei! Espere por mim!",
  str_homestory_N23dianying_90030201_211X1_dialog_content = "Esse final é demais! Chubb!",
  str_homestory_N23dianying_90030201_212_dialog_content = "Eu não posso dizer se é apenas sua natureza soberba ou atuação fenomenal, mas desmoronar assim foi um golpe de gênio, Chubb.",
  str_homestory_N23dianying_90030201_213_dialog_content = "Heyyyy, apenas sentindo que algo não está certo agora? Isso é uma reviravolta abrupta na história, Chubb!",
  str_homestory_N23dianying_90030201_214_dialog_content = "Por que você não explica? Prossiga!",
  str_homestory_N23dianying_90030201_215_dialog_content = "Bem, na maioria dos filmes e programas de televisão, quanto mais você quer saber, mais eles aumentam o suspense, Chubb.",
  str_homestory_N23dianying_90030201_216_dialog_content = "O Frost Dragon muito possivelmente já voou com ele!",
  str_homestory_N23dianying_90030201_217_dialog_content = "Mas a espada nem é um adereço, certo? Então, o que está acontecendo com o enredo, Chubb?",
  str_homestory_N23dianying_90030301_1_dialog_content = "Ufa! Pode ter levado dois dias, mas pelo menos tudo está se encaixando.",
  str_homestory_N23dianying_90030301_2_dialog_content = "Esses bandidos são loucos, destruindo um lugar tão artístico.",
  str_homestory_N23dianying_90030301_3_dialog_content = "Mas, felizmente, o piano escapou relativamente ileso...",
  str_homestory_N23dianying_90030301_3X1_dialog_content = "Parece caro, Chubb.",
  str_homestory_N23dianying_90030301_4_dialog_content = "Mas, felizmente, essa também foi a chance de convencer o patrão a trocar o piano por um palco.",
  str_homestory_N23dianying_90030301_5_dialog_content = "Depois disso, eu posso cantar para o conteúdo do meu coração...",
  str_homestory_N23dianying_90030301_5X1_dialog_content = "Quero baixar o volume, Chubb...",
  str_homestory_N23dianying_90030301_6_dialog_content = "Eu não posso acreditar que o chefe é tão mesquinho.",
  str_homestory_N23dianying_90030301_7_dialog_content = "Não está disposto a pagar pelos reparos do piano depois que ele foi danificado.",
  str_homestory_N23dianying_90030301_8_dialog_content = "E me mandando para o antigo armazém para algumas decorações antigas...",
  str_homestory_N23dianying_90030301_8X1_dialog_content = "O que é isso?",
  str_homestory_N23dianying_90030301_9_dialog_content = "<color=#e8d9bb>Ding—</color>",
  str_homestory_N23dianying_90030301_10_dialog_content = "Desculpe, mas estamos fechados—",
  str_homestory_N23dianying_90030301_11_dialog_content = "Huh? Você novamente?!",
  str_homestory_N23dianying_90030301_12_dialog_content = "Agora Agora. Isso não é maneira de receber clientes, Sr. Bartender.",
  str_homestory_N23dianying_90030301_12X1_dialog_content = "Encontramo-nos de novo, barman.",
  str_homestory_N23dianying_90030301_13_dialog_content = "Tenho alguns assuntos urgentes para discutir com um velho amigo hoje, então dois copos de Umbraton Encounter, por gentileza.",
  str_homestory_N23dianying_90030301_13X1_dialog_content = "Trouxe um velho amigo aqui para discutir negócios hoje, então dois copos do Reddiesel Special, por favor.",
  str_homestory_N23dianying_90030301_14_dialog_content = "Saiu fresco. Desculpe.",
  str_homestory_N23dianying_90030301_15_dialog_content = "Você pode agradecer aos seus lacaios malucos por isso, vindo aqui alguns dias atrás e destruindo o lugar!",
  str_homestory_N23dianying_90030301_16_dialog_content = "Ah, isso é uma pena. Parece que não poderei lhe oferecer uma bebida nesta ocasião.",
  str_homestory_N23dianying_90030301_16X1_dialog_content = "Ah, isso mesmo. Houve aquele... incidente.",
  str_homestory_N23dianying_90030301_17_dialog_content = "Você estava lá quando aconteceu! Não se faça de inocente comigo!",
  str_homestory_N23dianying_90030301_17X1_dialog_content = "Vamos tentar em outro lugar?",
  str_homestory_N23dianying_90030301_18_dialog_content = "Está bem. Estamos apenas repassando o contrato de qualquer maneira. Vamos fazer isso.",
  str_homestory_N23dianying_90030301_19_dialog_content = "A propósito, você poderia pedir ao barman para mudar a música para algo um pouco mais... refinado?",
  str_homestory_N23dianying_90030301_20_dialog_content = "Sua escolha de música deixa muito a desejar.",
  str_homestory_N23dianying_90030301_21_dialog_content = "O que você disse?!",
  str_homestory_N23dianying_90030301_22_dialog_content = "Este lugar todo precisa de uma reforma, na verdade.",
  str_homestory_N23dianying_90030301_23_dialog_content = "O que você disse?!",
  str_homestory_N23dianying_90030301_24_dialog_content = "Eu tenho seus caras lutando aqui para agradecer por isso também.",
  str_homestory_N23dianying_90030301_25_dialog_content = "Arruinou todas as decorações anteriores e até quebrou os móveis!",
  str_homestory_N23dianying_90030301_26_dialog_content = "Multar. Deixe-me voltar para você sobre isso um pouco mais tarde.",
  str_homestory_N23dianying_90030301_27_dialog_content = "A decoração aqui é um pouco... Bem, é bem ruim.",
  str_homestory_N23dianying_90030301_28_dialog_content = "Não quero ficar aqui um segundo a mais do que o absolutamente necessário.",
  str_homestory_N23dianying_90030301_29_dialog_content = "Basta pedir ao barman para alterar o registro, por favor.",
  str_homestory_N23dianying_90030301_29X1_dialog_content = "Hahaha! Por favor, não se importe meu amigo. É assim que ele fala.",
  str_homestory_N23dianying_90030301_30_dialog_content = "Também somos bons amigos do chefe aqui. Tenho certeza que ele não vai se importar.",
  str_homestory_N23dianying_90030301_30X1_dialog_content = "Eu sou um bom amigo do seu chefe. Ele não vai dizer nada se eu ocupar um pouco de espaço aqui.",
  str_homestory_N23dianying_90030301_30X2_dialog_content = "Vou explicar tudo para ele mais tarde. Você apenas pula e muda a música.",
  str_homestory_N23dianying_90030301_31_dialog_content = "Er... B-Chefe?",
  str_homestory_N23dianying_90030301_32_dialog_content = "... Multar. Eu entendi.",
  str_homestory_N23dianying_90030301_33_dialog_content = "Droga. Usando meu próprio chefe para me ameaçar.",
  str_homestory_N23dianying_90030301_34_dialog_content = "Este lugar não será nada além de um ponto de encontro de gangues a esse ritmo.",
  str_homestory_N23dianying_90030301_35_dialog_content = "Tenho de pensar numa forma de os impedir de voltarem.",
  str_homestory_N23dianying_90030301_36_dialog_content = "Eu sei! Vendo que este cavalheiro mais elegante gosta de seu ambiente rarefeito, eu tenho apenas o registro—",
  str_homestory_N23dianying_90030301_37_dialog_content = "Desculpe, não foi isso que combinamos. Não posso-",
  str_homestory_N23dianying_90030301_38_dialog_content = "Huh? O que deu no barman? Esta música-",
  str_homestory_N23dianying_90030301_38X1_dialog_content = "Estou empolgado, Chubb.",
  str_homestory_N23dianying_90030301_39_dialog_content = "Vou fazê-lo desligar.",
  str_homestory_N23dianying_90030301_39X1_dialog_content = "Uau, o garoto realmente tocou algo que eu gosto.",
  str_homestory_N23dianying_90030301_39X2_dialog_content = "Mas pode ser um pouco alto para você. Vou fazê-lo desligar.",
  str_homestory_N23dianying_90030301_40_dialog_content = "Tudo bem.",
  str_homestory_N23dianying_90030301_41_dialog_content = "A melodia e o ritmo... Isso me lembra quando tocávamos juntos em turnê.",
  str_homestory_N23dianying_90030301_42_dialog_content = "Estamos indo para um flashback, Chubb?!",
  str_homestory_N23dianying_90030301_43_dialog_content = "Então você se lembra daqueles dias.",
  str_homestory_N23dianying_90030301_44_dialog_content = "Sei que nossos caminhos divergiram ao longo do tempo, pois assumimos responsabilidades diferentes.",
  str_homestory_N23dianying_90030301_45_dialog_content = "Embora eu entenda nossas diferentes posições, às vezes ainda me emociono.",
  str_homestory_N23dianying_90030301_46_dialog_content = "Eu também sou.",
  str_homestory_N23dianying_90030301_47_dialog_content = "... Você sabe o que? Deixe-me voltar e tentar fazer as coisas andarem com o contrato.",
  str_homestory_N23dianying_90030301_47X1_dialog_content = "... E as vezes que suas Chaves Rediesel roubaram nossa carga.",
  str_homestory_N23dianying_90030301_47X2_dialog_content = "Não vamos esquecer a vez em que o Senhor das Sombras me mandou atrás de você, e eu persegui você pelo Deserto Rediesel por três dias e três noites inteiras!",
  str_homestory_N23dianying_90030301_47X3_dialog_content = "Ei, vamos lá! Não deveríamos estar fazendo um filme? O que há com a seriedade de repente?",
  str_homestory_N23dianying_90030301_47X4_dialog_content = "... Desculpe. Eu só vejo vermelho sempre que tenho que olhar para o rosto dele.",
  str_homestory_N23dianying_90030301_47X5_dialog_content = "Onde está o roteiro?",
  str_homestory_N23dianying_90030301_47X6_dialog_content = "Por que essa parte não foi cortada, Chubb?!",
  str_homestory_N23dianying_90030301_47X7_dialog_content = "Ah sim, então que tal eu voltar e tentar fazer as coisas andarem com o contrato.",
  str_homestory_N23dianying_90030301_48_dialog_content = "Veja isso como ajudar um velho amigo.",
  str_homestory_N23dianying_90030301_49_dialog_content = "Tão fácil, Chubb?",
  str_homestory_N23dianying_90030301_50_dialog_content = "Bem, eu realmente sou grato.",
  str_homestory_N23dianying_90030301_51_dialog_content = "Uau, eu nunca soube que você era tão hábil em ler a sala! Temos de lhe agradecer pelo sucesso destas negociações!",
  str_homestory_N23dianying_90030301_52_dialog_content = "Você deve saber sobre nossa antiga banda, o Rockin' Dragons, antes de escolher esse disco, certo?",
  str_homestory_N23dianying_90030301_52X1_dialog_content = "Oh sério? Muito obrigado!",
  str_homestory_N23dianying_90030301_52X2_dialog_content = "Uau, eu nunca soube que você era tão hábil em ler a sala! Temos de lhe agradecer pelo sucesso destas negociações!",
  str_homestory_N23dianying_90030301_52X3_dialog_content = "Você deve saber sobre nossa antiga banda, o Rockin' Dragons, antes de escolher esse disco, certo?",
  str_homestory_N23dianying_90030301_53_dialog_content = "Chu! Que grande mal-entendido, Chubb!",
  str_homestory_N23dianying_90030301_54_dialog_content = "Eu não sou-",
  str_homestory_N23dianying_90030301_55_dialog_content = "Já que o barman provou ser tão confiável, posso fazer outro pedido?",
  str_homestory_N23dianying_90030301_56_dialog_content = "Tenho aqui uma mensagem muito confidencial e extremamente importante. Um intermediário estará junto mais tarde para recolhê-lo.",
  str_homestory_N23dianying_90030301_56X1_dialog_content = "Bem, é óbvio porque o chefe escolheu você para administrar este lugar. Bom trabalho!",
  str_homestory_N23dianying_90030301_56X2_dialog_content = "Já que o barman provou ser tão confiável, posso fazer outro pedido?",
  str_homestory_N23dianying_90030301_56X3_dialog_content = "Tenho aqui uma mensagem muito confidencial e extremamente importante. Um intermediário estará junto mais tarde para recolhê-lo.",
  str_homestory_N23dianying_90030301_57_dialog_content = "Espere, eu não...",
  str_homestory_N23dianying_90030301_58_dialog_content = "Não se preocupe! É realmente muito simples.",
  str_homestory_N23dianying_90030301_59_dialog_content = "O contato usará a palavra de código \"Beauty Under the Moon\". Apenas entregue a carta quando ouvir isso.",
  str_homestory_N23dianying_90030301_60_dialog_content = "Tenho outros negócios para cuidar, então vou me despedir.",
  str_homestory_N23dianying_90030301_60X1_dialog_content = "Não se preocupe! É realmente muito simples.",
  str_homestory_N23dianying_90030301_60X2_dialog_content = "O contato usará a palavra de código \"Beauty Under the Moon\". Apenas entregue a carta quando ouvir isso.",
  str_homestory_N23dianying_90030301_60X3_dialog_content = "Ainda tenho assuntos muito importantes para tratar, então vou me despedir.",
  str_homestory_N23dianying_90030301_61_dialog_content = "Ei! eu não terminei!",
  str_homestory_N23dianying_90030301_62_dialog_content = "Deixe as pessoas terminarem, Chubb!",
  str_homestory_N23dianying_90030301_63_dialog_content = "Realmente... Cada um desses caras...",
  str_homestory_N23dianying_90030301_64_dialog_content = "<color=#e8d9bb>Ding—</color>",
  str_homestory_N23dianying_90030301_65_dialog_content = "Agora quem é?! Eles não veem o sinal de \"FECHADO\" na porta?",
  str_homestory_N23dianying_90030301_66_dialog_content = "Xerife chamando! Perdoe a interrupção, mas estou aqui sobre a briga que estourou aqui alguns dias atrás.",
  str_homestory_N23dianying_90030301_66X1_dialog_content = "Xerife chamando! Perdoe a interrupção, mas estou aqui sobre a briga que estourou aqui alguns dias atrás.",
  str_homestory_N23dianying_90030301_67_dialog_content = "O dono está por perto?",
  str_homestory_N23dianying_90030301_67X1_dialog_content = "O dono está por perto?",
  str_homestory_N23dianying_90030301_68_dialog_content = "Xerife? No momento ideal!",
  str_homestory_N23dianying_90030301_69_dialog_content = "Eu sou o barman aqui, e fui testemunha ocular de uma discussão criminal agora mesmo. Eles até me deram uma carta confidencial.",
  str_homestory_N23dianying_90030301_70_dialog_content = "Eu vou te contar tudo o que sei se você puder impedir aqueles bandidos de pisar aqui de novo!",
  str_homestory_N23dianying_90030301_71_dialog_content = "Uma carta confidencial de gangue?",
  str_homestory_N23dianying_90030301_71X1_dialog_content = "Uma carta confidencial de gangue?",
  str_homestory_N23dianying_90030301_71X2_dialog_content = "Isso mesmo. Se você for atrás deles agora, aqueles que me deram a carta não podem ter ido longe.",
  str_homestory_N23dianying_90030301_72_dialog_content = "Você realmente tem sido de muita ajuda. Obrigado pela sua cooperação, barman.",
  str_homestory_N23dianying_90030301_73_dialog_content = "Assim que souber o que está acontecendo, serei responsável por manter este lugar seguro.",
  str_homestory_N23dianying_90030301_74_dialog_content = "Bem, então vá em frente!",
  str_homestory_N23dianying_90030301_74X1_dialog_content = "Preciso ver o que diz antes de julgar a veracidade de suas informações.",
  str_homestory_N23dianying_90030301_74X2_dialog_content = "Afinal, não consigo entender por que eles confiariam um item tão importante a você.",
  str_homestory_N23dianying_90030301_74X3_dialog_content = "Tudo bem, apenas continue com isso.",
  str_homestory_N23dianying_90030301_75_dialog_content = "\"Minha querida Donzela da Lua,\"",
  str_homestory_N23dianying_90030301_76_dialog_content = "\"Aprecio seu entusiasmo sincero e admiro sua franqueza corajosa.\"",
  str_homestory_N23dianying_90030301_77_dialog_content = "\"Mas, mais desculpas, eu não sinto o mesmo\"...",
  str_homestory_N23dianying_90030301_78_dialog_content = "É uma carta de amor, Chubb!",
  str_homestory_N23dianying_90030301_79_dialog_content = "O que você está fazendo?",
  str_homestory_N23dianying_90030301_80_dialog_content = "Isto é... uma carta para mim?",
  str_homestory_N23dianying_90030301_81_dialog_content = "Isso, isso é...",
  str_homestory_N23dianying_90030301_82_dialog_content = "Meu nom de plume é \"Beauty Under the Moon\"...",
  str_homestory_N23dianying_90030301_83_dialog_content = "Isso foi endereçado a mim, correto?",
  str_homestory_N23dianying_90030301_84_dialog_content = "Y-Sim.",
  str_homestory_N23dianying_90030301_85_dialog_content = "Eu claramente acabei de ouvir, que ele foi incapaz de retribuir meus sentimentos...",
  str_homestory_N23dianying_90030301_86_dialog_content = "No final do dia, eu ainda não consegui fazer isso acontecer.",
  str_homestory_N23dianying_90030301_87_dialog_content = "Ei! Por que você está tocando nosso toca-discos?!",
  str_homestory_N23dianying_90030301_87X1_dialog_content = "Pffff—",
  str_homestory_N23dianying_90030301_87X2_dialog_content = "Ha ha ha!",
  str_homestory_N23dianying_90030301_87X3_dialog_content = "Caronte, acalme-se! Chubb.",
  str_homestory_N23dianying_90030301_88_dialog_content = "Eu o conheci há um mês, sob a lua cheia.",
  str_homestory_N23dianying_90030301_89_dialog_content = "Eu estava me escondendo de alguns bandidos na época, e ele me resgatou.",
  str_homestory_N23dianying_90030301_90_dialog_content = "Er... Por que ela está nos contando isso?",
  str_homestory_N23dianying_90030301_91_dialog_content = "Perguntei em todos os lugares da cidade, antes de finalmente descobrir quem ele era.",
  str_homestory_N23dianying_90030301_92_dialog_content = "Mas eu estava iludido se eu pensava que um homem de sua estatura poderia se apaixonar por alguém como eu.",
  str_homestory_N23dianying_90030301_93_dialog_content = "É por isso que você escolheu usar um pseudônimo e escrever uma carta para ele?",
  str_homestory_N23dianying_90030301_93X1_dialog_content = "É por isso que você escolheu usar um pseudônimo e escrever uma carta para ele?",
  str_homestory_N23dianying_90030301_94_dialog_content = "Sim... Porque eu achava que, aconteça o que acontecer, eu não me deixaria me arrepender.",
  str_homestory_N23dianying_90030301_95_dialog_content = "Mas aprendi que alguns abismos são grandes demais para serem cruzados apenas com bravura.",
  str_homestory_N23dianying_90030301_95X1_dialog_content = "É admirável que uma dama tenha tanta coragem.",
  str_homestory_N23dianying_90030301_95X2_dialog_content = "É uma perda dele rejeitar uma dama tão elegante.",
  str_homestory_N23dianying_90030301_96_dialog_content = "Eu certamente posso entender como você se sente, Moon Maiden.",
  str_homestory_N23dianying_90030301_97_dialog_content = "Essa simpatia está rastejando?!",
  str_homestory_N23dianying_90030301_98_dialog_content = "O fato de você ter tido a coragem de fazer isso em primeiro lugar é admirável.",
  str_homestory_N23dianying_90030301_99_dialog_content = "Acho que você não deveria desistir de seu coração tão rápido. Ajude-o a entender você.",
  str_homestory_N23dianying_90030301_100_dialog_content = "Não basta jogar a toalha no primeiro obstáculo.",
  str_homestory_N23dianying_90030301_101_dialog_content = "Obrigado... Você é a primeira pessoa a me dizer isso.",
  str_homestory_N23dianying_90030301_101X1_dialog_content = "Eu sou o xerife por aqui, então se você precisar de alguma coisa no futuro, não deixe de me encontrar.",
  str_homestory_N23dianying_90030301_101X2_dialog_content = "E... peço desculpas por ler sua carta. Eu não deveria ter feito isso.",
  str_homestory_N23dianying_90030301_101X3_dialog_content = "Eu acredito que você tinha apenas boas intenções.",
  str_homestory_N23dianying_90030301_101X4_dialog_content = "Obrigado por sua gentileza e compreensão.",
  str_homestory_N23dianying_90030301_101X5_dialog_content = "Bem, quanto a você, Sr. Charon.",
  str_homestory_N23dianying_90030301_101X6_dialog_content = "Ah... Sim?",
  str_homestory_N23dianying_90030301_101X7_dialog_content = "Eu não deveria ser o Sr. Bartender?",
  str_homestory_N23dianying_90030301_101X8_dialog_content = "Não posso perdoá-lo, por se intrometer nos assuntos mais pessoais de uma jovem.",
  str_homestory_N23dianying_90030301_101X9_dialog_content = "Tal comportamento repreensível deve ser punido pela lei e condenado pela moralidade comum!",
  str_homestory_N23dianying_90030301_101X10_dialog_content = "...!",
  str_homestory_N23dianying_90030301_101X11_dialog_content = "Diminua o tom, Pittman!",
  str_homestory_N23dianying_90030301_101X12_dialog_content = "Ele está entrando um pouco demais no personagem, Chubb!",
  str_homestory_N23dianying_90030301_101X13_dialog_content = "Espera, espera, espera!",
  str_homestory_N23dianying_90030301_101X14_dialog_content = "Não estamos filmando? O que diz o roteiro?",
  str_homestory_N23dianying_90030301_101X15_dialog_content = "Não é que eu queria ler!",
  str_homestory_N23dianying_90030301_101X16_dialog_content = "Hmph, ainda gemendo.",
  str_homestory_N23dianying_90030301_101X17_dialog_content = "Tome seu castigo!",
  str_homestory_N23dianying_90030301_101X18_dialog_content = "Espere aí!",
  str_homestory_N23dianying_90030301_101X19_dialog_content = "Não vá quebrar meu set, OU os adereços!",
  str_homestory_N23dianying_90030301_102_dialog_content = "Eu sou o xerife por aqui, então se você precisar de alguma coisa no futuro, não deixe de me encontrar.",
  str_homestory_N23dianying_90030301_103_dialog_content = "De qualquer forma, eu ainda tenho coisas para fazer, então eu deveria estar indo. Até a próxima.",
  str_homestory_N23dianying_90030301_104_dialog_content = "Espere! E a luta?",
  str_homestory_N23dianying_90030301_105_dialog_content = "Com base no que acabei de ver, não estou convencido de que você seja capaz de fornecer informações confiáveis.",
  str_homestory_N23dianying_90030301_106_dialog_content = "É muito desprezível se intrometer nos assuntos mais privados de uma dama.",
  str_homestory_N23dianying_90030301_107_dialog_content = "Vou avaliar e julgar a mim mesmo. Adeus.",
  str_homestory_N23dianying_90030301_108_dialog_content = "Como isso é possível...",
  str_homestory_N23dianying_90030301_109_dialog_content = "Aquele homem agora, ele era... realmente o xerife?",
  str_homestory_N23dianying_90030301_110_option_content = "Peça desculpas sinceramente",
  str_homestory_N23dianying_90030301_110X1_dialog_content = "Não fique aí parado, atendente! Faça seu pedido de desculpas!",
  str_homestory_N23dianying_90030301_111_dialog_content = "De uma vez só.",
  str_homestory_N23dianying_90030301_112_dialog_content = "Peço desculpas por abrir uma carta pessoal tão importante sem permissão.",
  str_homestory_N23dianying_90030301_113_dialog_content = "Está bem. Afinal, foi um julgamento feito em um momento crítico para o benefício da organização.",
  str_homestory_N23dianying_90030301_114_dialog_content = "Organização?",
  str_homestory_N23dianying_90030301_115_dialog_content = "A carta foi escrita em código. Parecia apenas uma carta de amor.",
  str_homestory_N23dianying_90030301_116_dialog_content = "Embora houvesse um risco inerente em abri-lo na frente do xerife... Parece que nos safamos, já que ela não estava nem um pouco desconfiada.",
  str_homestory_N23dianying_90030301_117_dialog_content = "E a Night Impression faz jus à sua reputação de estabelecimento confiável.",
  str_homestory_N23dianying_90030301_118_dialog_content = "Espere, você quer dizer que você realmente faz parte da gangue?",
  str_homestory_N23dianying_90030301_119_dialog_content = "Tudo isso foi inventado na hora?",
  str_homestory_N23dianying_90030301_120_dialog_content = "Sim.",
  str_homestory_N23dianying_90030301_121_dialog_content = "Uau! Eu não esperava isso, Chubb!",
  str_homestory_N23dianying_90030301_122_dialog_content = "De qualquer forma... Agora que recuperei a carta com segurança, devo ir para minha próxima parada nesta missão.",
  str_homestory_N23dianying_90030301_123_dialog_content = "Vejo você, Sr. Barman.",
  str_homestory_N23dianying_90030301_124_dialog_content = "...",
  str_homestory_N23dianying_90030301_125_dialog_content = "O que acabou de acontecer?!",
  str_homestory_N23dianying_90030301_126_option_content = "Aconselhe-a a desistir",
  str_homestory_N23dianying_90030301_126X1_dialog_content = "Vamos, atendente, o que você está esperando? Esta é a parte em que você deve tentar convencê-la a desistir do relacionamento!",
  str_homestory_N23dianying_90030301_127_dialog_content = "Tá bom.",
  str_homestory_N23dianying_90030301_128_dialog_content = "Isso mesmo, Moon Maiden... Há algo que preciso te dizer.",
  str_homestory_N23dianying_90030301_129_dialog_content = "Acontece que o homem que você admira é uma figura perigosa na gangue!",
  str_homestory_N23dianying_90030301_130_dialog_content = "...!",
  str_homestory_N23dianying_90030301_131_dialog_content = "A Xerife não acreditou em mim, e é por isso que ela encorajou você a ir atrás disso.",
  str_homestory_N23dianying_90030301_132_dialog_content = "Mas eu ainda aconselho você a simplesmente ir embora. E se ele não for realmente o cavalheiro de bom coração que você pensa que é?",
  str_homestory_N23dianying_90030301_133_dialog_content = "... Então você queria revelar sua verdadeira identidade ao xerife?",
  str_homestory_N23dianying_90030301_134_dialog_content = "Sim. Mesmo que o xerife não acredite em mim, não vou parar de seguir as pistas.",
  str_homestory_N23dianying_90030301_135_dialog_content = "...",
  str_homestory_N23dianying_90030301_136_dialog_content = "Donzela da Lua?",
  str_homestory_N23dianying_90030301_137_dialog_content = "O-o que você vai fazer?!",
  str_homestory_N23dianying_90030301_138_dialog_content = "A princípio pensei que o xerife o havia coagido a ler a carta.",
  str_homestory_N23dianying_90030301_139_dialog_content = "Aquele cavalheiro cometeu um erro...?",
  str_homestory_N23dianying_90030301_140_dialog_content = "O-o que você quer dizer?",
  str_homestory_N23dianying_90030301_141_dialog_content = "A carta foi escrita em código. Parecia apenas uma carta de amor.",
  str_homestory_N23dianying_90030301_142_dialog_content = "A fim de evitar exatamente essa crise.",
  str_homestory_N23dianying_90030301_143_dialog_content = "E eu sou um dos jogadores nesta missão clandestina.",
  str_homestory_N23dianying_90030301_144_dialog_content = "Uau! Eu não esperava isso, Chubb!",
  str_homestory_N23dianying_90030301_145_dialog_content = "Espere! Então você é realmente parte da gangue?!",
  str_homestory_N23dianying_90030301_146_dialog_content = "Sim... Desculpe o subterfúgio.",
  str_homestory_N23dianying_90030301_147_dialog_content = "Mas a segurança da organização é primordial. Então, por favor, Sr. Barman...",
  str_homestory_N23dianying_90030301_148_dialog_content = "Você vai ter que ficar de boca fechada... para sempre.",
  str_homestory_N23dianying_90030301_149_dialog_content = "O-o que você está fazendo?",
  str_homestory_N23dianying_90030301_150_dialog_content = "Fique atrás!",
  str_homestory_N23dianying_90030301_151_option_content = "Identidade da pergunta",
  str_homestory_N23dianying_90030301_151X1_dialog_content = "Afogou suas linhas? Você está questionando a identidade dela, atendente!",
  str_homestory_N23dianying_90030301_152_dialog_content = "Parece correto.",
  str_homestory_N23dianying_90030301_153_dialog_content = "Então, a Donzela da Lua?",
  str_homestory_N23dianying_90030301_154_dialog_content = "Claro?",
  str_homestory_N23dianying_90030301_155_dialog_content = "Você é realmente apenas um pretendente rejeitado?",
  str_homestory_N23dianying_90030301_156_dialog_content = "...",
  str_homestory_N23dianying_90030301_157_dialog_content = "Não é bom saber muito, Sr. Bartender.",
  str_homestory_N23dianying_90030301_158_dialog_content = "Mas vou indo, já que tenho a carta.",
  str_homestory_N23dianying_90030301_159_dialog_content = "Eu sabia que algo cheirava a peixe.",
  str_homestory_N23dianying_90030301_160_dialog_content = "Tenho certeza de que há mais do que aparenta nessa carta. É melhor eu anotar o que disse, enquanto ainda me lembro.",
  str_homestory_N23dianying_90030301_161_dialog_content = "Agora, onde está uma caneta e papel...",
  str_homestory_N23dianying_90030301_162_dialog_content = "Você simplesmente não poderia deixá-lo sozinho, poderia?",
  str_homestory_N23dianying_90030301_163_dialog_content = "V-você ainda está—",
  str_homestory_N23dianying_90030301_164_dialog_content = "Chu! Desfecho! Chubb!",
  str_homestory_N23dianying_90030301_165_dialog_content = "Os protagonistas dos filmes nunca verificam a sala, Chubb!",
  str_homestory_N23dianying_90030301_166_dialog_content = "Por que aquele cavalheiro confiaria um item tão importante a você?",
  str_homestory_N23dianying_90030301_167_dialog_content = "A menos que fosse tudo parte do plano?",
  str_homestory_N23dianying_90030301_168_dialog_content = "Independentemente disso, para evitar que surjam distrações inesperadas. Por que não damos um pequeno passeio juntos, Sr. Bartender?",
  str_homestory_N23dianying_90030301_169_dialog_content = "Espere! O que você está fazendo?!",
  str_homestory_N23dianying_90030301_170_dialog_content = "Fique atrás!",
  str_homestory_N23dianying_90030301_171_dialog_content = "Não leve as coisas longe demais, seu par de murmúrios...",
  str_homestory_N23dianying_90030301_172_dialog_content = "Relaxe, Sr. Barman. Não queremos incomodá-lo.",
  str_homestory_N23dianying_90030301_172X1_dialog_content = "Eu sou um bom amigo do seu chefe. Ele não vai dizer nada se eu ocupar um pouco de espaço aqui.",
  str_homestory_N23dianying_90030301_173_dialog_content = "Também somos bons amigos do chefe. tenho certeza que ele não vai se importar",
  str_homestory_N23dianying_90030301_174_dialog_content = "Er... B-Chefe?",
  str_homestory_N23dianying_90030301_175_dialog_content = "... Multar. Eu entendi.",
  str_homestory_N23dianying_90030301_176_dialog_content = "Droga. Usando meu próprio chefe para me ameaçar.",
  str_homestory_N23dianying_90030301_177_dialog_content = "Este lugar não será nada além de um ponto de encontro de gangues a esse ritmo.",
  str_homestory_N23dianying_90030301_178_dialog_content = "Desculpe, não foi isso que combinamos. Não tenho como aceitar.",
  str_homestory_N23dianying_90030301_179_dialog_content = "Depois de todos esses anos de amizade, você não pode ceder um pouco?",
  str_homestory_N23dianying_90030301_179X1_dialog_content = "Você tem sido como um irmão para mim por todos esses anos. Você não pode encontrar um pouco de espaço de manobra?",
  str_homestory_N23dianying_90030301_180_dialog_content = "É apenas um negócio. Afinal, vale tudo no amor e nos shoppings. São campos de batalha, não lugares para fazer amigos.",
  str_homestory_N23dianying_90030301_181_dialog_content = "Se você estivesse no meu lugar, faria exatamente o mesmo.",
  str_homestory_N23dianying_90030301_182_dialog_content = "E você realmente não pensa em mim como um amigo de verdade, a julgar pela forma como você adulterou o contrato da última vez.",
  str_homestory_N23dianying_90030301_183_dialog_content = "Ah, isso foi apenas um pequeno mal-entendido.",
  str_homestory_N23dianying_90030301_184_dialog_content = "Oh? A última vez que você interferiu em nossos negócios também foi um mal-entendido?",
  str_homestory_N23dianying_90030301_185_dialog_content = "Sobre isso...",
  str_homestory_N23dianying_90030301_186_dialog_content = "Ou o tempo antes disso, quando você correu para o cheiro do xerife?",
  str_homestory_N23dianying_90030301_187_dialog_content = "Os poucos caras que nos restaram fizeram o possível para proteger a mercadoria do chefe, mas pagamos um preço muito alto.",
  str_homestory_N23dianying_90030301_188_dialog_content = "...",
  str_homestory_N23dianying_90030301_189_dialog_content = "Eu realmente não consigo entender por que aqueles caras lá em cima ainda estão dispostos a trabalhar com você.",
  str_homestory_N23dianying_90030301_190_dialog_content = "Mas eu... estive esperando para te mostrar o quanto você me deixou com raiva.",
  str_homestory_N23dianying_90030301_191_dialog_content = "E você OUSA usar a palavra 'amigo' comigo?!",
  str_homestory_N23dianying_90030301_192_dialog_content = "Agora, agora - se você vai lutar, leve-o para outro lugar.",
  str_homestory_N23dianying_90030301_193_dialog_content = "É assim que as negociações funcionam?!",
  str_homestory_N23dianying_90030301_194_dialog_content = "Saia da pretensão. Todo mundo está fora de si. Não há certo ou errado aqui.",
  str_homestory_N23dianying_90030301_195_dialog_content = "Você não forneceu secretamente informações sobre nós para a Gangue Lionhead no passado?",
  str_homestory_N23dianying_90030301_196_dialog_content = "Estamos apenas retribuindo o favor. Equilibrando a balança.",
  str_homestory_N23dianying_90030301_197_dialog_content = "Parece que guardas muito rancor contra nós.",
  str_homestory_N23dianying_90030301_198_dialog_content = "Então vamos acertar todas as contas hoje, aqui e agora.",
  str_homestory_N23dianying_90030301_199_dialog_content = "Tudo bem por mim se você for corajoso o suficiente para admitir seus erros.",
  str_homestory_N23dianying_90030301_200_dialog_content = "Não briguem aqui, vocês dois!",
  str_homestory_N23dianying_90030301_201_dialog_content = "Todos simplesmente param! Abaixe suas armas!",
  str_homestory_N23dianying_90030301_202_dialog_content = "Acabei de arrumar o lugar!",
  str_homestory_N23dianying_90030301_202X1_dialog_content = "Sempre disse que era um mal-entendido.",
  str_homestory_N23dianying_90030301_202X2_dialog_content = "Não podemos escrever da mesma maneira rígida que você.",
  str_homestory_N23dianying_90030301_202X3_dialog_content = "Oh? Então da última vez, quando você roubou nossa mercadoria, também foi um mal-entendido?",
  str_homestory_N23dianying_90030301_202X4_dialog_content = "Bom...",
  str_homestory_N23dianying_90030301_202X5_dialog_content = "O Senhor das Sombras me fez persegui-lo pelo deserto de Rediesel por três dias e três noites inteiros.",
  str_homestory_N23dianying_90030301_202X6_dialog_content = "Você apenas deu voltas e voltas, fazendo uma bagunça de tudo antes de jogar tudo de volta para mim.",
  str_homestory_N23dianying_90030301_202X7_dialog_content = "Isso também foi um mal-entendido, não é?",
  str_homestory_N23dianying_90030301_202X8_dialog_content = "Ei, não estamos fazendo um filme?",
  str_homestory_N23dianying_90030301_202X9_dialog_content = "Você está escolhendo agora trazer à tona tudo isso?",
  str_homestory_N23dianying_90030301_202X10_dialog_content = "Taki, Sinsa, por favor, acalmem-se!",
  str_homestory_N23dianying_90030301_202A1_dialog_content = "Eles começaram a lutar!",
  str_homestory_N23dianying_90030301_202X11_dialog_content = "Sinto muito, mas acho que não podemos continuar as filmagens.",
  str_homestory_N23dianying_90030301_202X12_dialog_content = "Eu mal reprimi minha raiva desde que vi seu rosto pela primeira vez no set.",
  str_homestory_N23dianying_90030301_202X13_dialog_content = "Fascinante. Então o que você vai fazer sobre isso? Quer tango?",
  str_homestory_N23dianying_90030301_202X14_dialog_content = "Pode vir.",
  str_homestory_N23dianying_90030301_202X15_dialog_content = "SAIA se você for lutar! Não destrua o set ou os adereços!",
  str_homestory_N23dianying_90030401_1_dialog_content = "Você se sente mal, Sua Majestade?",
  str_homestory_N23dianying_90030401_2_dialog_content = "Novio disse que você não tem se alimentado bem ultimamente.",
  str_homestory_N23dianying_90030401_3_dialog_content = "Eles estão preocupados e estão tentando encontrar novas receitas para você.",
  str_homestory_N23dianying_90030401_4_dialog_content = "Desculpe tê-los preocupados, Lola.",
  str_homestory_N23dianying_90030401_5_dialog_content = "Eu só não tenho muito apetite ultimamente. Não há necessidade de preocupações.",
  str_homestory_N23dianying_90030401_6_dialog_content = "Por que não experimentar um pouco de mel que acabei de coletar? É realmente doce!",
  str_homestory_N23dianying_90030401_S6_dialog_content = "Ou, se você não quer mel, temos alguns pratos novos.",
  str_homestory_N23dianying_90030401_7_dialog_content = "O mel é bom, mas o açúcar realmente não é bom para o corpo.",
  str_homestory_N23dianying_90030401_8_dialog_content = "Huh? Quem é Você?",
  str_homestory_N23dianying_90030401_X8_dialog_content = "Garotinha, muitas sobremesas vão te deixar obesa.",
  str_homestory_N23dianying_90030401_S8_dialog_content = "Majestade?",
  str_homestory_N23dianying_90030401_S9_dialog_content = "Eu sou o Chef Eve, contratado pelo Sr. Novio para fazer novos pratos para você.",
  str_homestory_N23dianying_90030401_9_dialog_content = "Minhas desculpas, Vossa Majestade.",
  str_homestory_N23dianying_90030401_10_dialog_content = "Eu sou o Chef Fleur, contratado pelo Sr. Novio para fazer novos pratos para você.",
  str_homestory_N23dianying_90030401_11_dialog_content = "Eu venho do Deserto Rediesel, longe de Northland.",
  str_homestory_N23dianying_90030401_12_dialog_content = "Confio que poderei trazer-lhe pratos que você nunca provou antes.",
  str_homestory_N23dianying_90030401_13_dialog_content = "Veja esta cerveja Rediesel? Isso é diferente de qualquer bebida que você tem aqui.",
  str_homestory_N23dianying_90030401_14_dialog_content = "Tenho certeza de que seu sabor suave e único irá excitar seu paladar.",
  str_homestory_N23dianying_90030401_X14_dialog_content = "Eu sou o novo chef contratado por aquele cara bonito do Novio.",
  str_homestory_N23dianying_90030401_X15_dialog_content = "Eu sou do Deserto Rediesel e trouxe pratos que você nunca ouviu falar comigo.",
  str_homestory_N23dianying_90030401_X16_dialog_content = "Este é o Palácio de Inverno. Temos todos os pratos de todos os cantos do continente!",
  str_homestory_N23dianying_90030401_X17_dialog_content = "Duvido que seja o caso, Garotinha.",
  str_homestory_N23dianying_90030401_X18_dialog_content = "Veja esta cerveja Rediesel? Isso é diferente de qualquer bebida que você tem aqui.",
  str_homestory_N23dianying_90030401_X19_dialog_content = "É uma receita exclusiva do Deserto Rediesel, e é transmitida e não encontrada em nenhum registro.",
  str_homestory_N23dianying_90030401_S14_dialog_content = "Não só isso, é muito mais estimulante do que qualquer outra bebida também.",
  str_homestory_N23dianying_90030401_S15_dialog_content = "Última vez, PlayerName só tomei alguns goles com meu irmão e...",
  str_homestory_N23dianying_90030401_S16_dialog_content = "E-Espere! Isso não está no roteiro, Eve!",
  str_homestory_N23dianying_90030401_S17_dialog_content = "Oh, certo! Então, qual é a minha linha?",
  str_homestory_N23dianying_90030401_S18_dialog_content = "Ah, e este Dragão Dourado de Quatro Pernas.",
  str_homestory_N23dianying_90030401_15_dialog_content = "Com certeza tem um aroma único.",
  str_homestory_N23dianying_90030401_16_dialog_content = "Você tem razão! Já estou sentindo o cheiro daqui!",
  str_homestory_N23dianying_90030401_X20_dialog_content = "Este dragão dourado de quatro patas.",
  str_homestory_N23dianying_90030401_17_dialog_content = "E este Dragão Dourado de Quatro Pernas.",
  str_homestory_N23dianying_90030401_18_dialog_content = "É feito de lagartos do deserto da parte mais profunda do deserto. A carne é firme com uma pele crocante.",
  str_homestory_N23dianying_90030401_19_dialog_content = "É uma das comidas mais famosas do Deserto Rediesel.",
  str_homestory_N23dianying_90030401_20_dialog_content = "Soa bem.",
  str_homestory_N23dianying_90030401_21_dialog_content = "Uhm... E-Isso é diferente.",
  str_homestory_N23dianying_90030401_22_dialog_content = "Quanto ao Desert Jewel, é o verdadeiro prato de assinatura.",
  str_homestory_N23dianying_90030401_23_dialog_content = "É feito de órgãos internos de vermes da areia, uma criatura exclusiva do deserto de Rediesel.",
  str_homestory_N23dianying_90030401_24_dialog_content = "I-órgãos internos dos vermes da areia!?",
  str_homestory_N23dianying_90030401_25_dialog_content = "Isso mesmo. Eles são temperados com rediesel, e nosso tempero exclusivo, depois torrados até que a pele fique levemente carbonizada.",
  str_homestory_N23dianying_90030401_26_dialog_content = "É aromático, suculento e altamente nutritivo—",
  str_homestory_N23dianying_90030401_27_dialog_content = "Para para para! O suficiente!",
  str_homestory_N23dianying_90030401_28_dialog_content = "Vocês Rediesel Wrench realmente comem coisas estranhas!",
  str_homestory_N23dianying_90030401_29_dialog_content = "Como seu estômago aguenta?",
  str_homestory_N23dianying_90030401_30_dialog_content = "Calma, Lola. Estamos fazendo um anúncio lido aqui!",
  str_homestory_N23dianying_90030401_31_dialog_content = "S-Desculpe...",
  str_homestory_N23dianying_90030401_32_dialog_content = "Isso com certeza soa intrigante. Você tem que nos mostrar os pratos.",
  str_homestory_N23dianying_90030401_X32_dialog_content = "Isso com certeza soa intrigante. Você tem que nos mostrar os pratos.",
  str_homestory_N23dianying_90030401_33_dialog_content = "Prazer, Vossa Majestade.",
  str_homestory_N23dianying_90030401_X33_dialog_content = "Rediesel gourmet, o sabor que até intriga a Rainha do Norte.",
  str_homestory_N23dianying_90030401_X34_dialog_content = "O Rediesel Foodfest já está disponível no Rediesel Desert! Por apenas quatro vezes por ano!",
  str_homestory_N23dianying_90030401_X35_dialog_content = "Você pode até me encontrar lá se tiver sorte.",
  str_homestory_N23dianying_90030401_S33_dialog_content = "Isso com certeza soa intrigante. Você tem que nos mostrar os pratos.",
  str_homestory_N23dianying_90030401_S34_dialog_content = "Prazer, Vossa Majestade!",
  str_homestory_N23dianying_90030401_34_dialog_content = "Rediesel gourmet, o sabor que até anima a Rainha do Norte.",
  str_homestory_N23dianying_90030401_35_dialog_content = "O Rediesel Foodfest já está disponível no Rediesel Desert! Por apenas quatro vezes por ano!",
  str_homestory_N23dianying_90030401_36_dialog_content = "Interessado? Entre em contato com a Odd Jobs, nosso colaborador na Umbraton!",
  str_homestory_N23dianying_90030401_37_dialog_content = "Grandes descontos para grupos e outras grandes ofertas para os primeiros 100 inquiridores!",
  str_homestory_N23dianying_90030401_38_dialog_content = "Não perca!",
  str_homestory_N23dianying_90030501_1_dialog_content = "Você está bem, senhorita Vice?",
  str_homestory_N23dianying_90030501_2_dialog_content = "Oh, me desculpe. Eu apaguei por um momento lá.",
  str_homestory_N23dianying_90030501_3_dialog_content = "O que você estava dizendo?",
  str_homestory_N23dianying_90030501_X1_dialog_content = "Diretor? Você está bem?",
  str_homestory_N23dianying_90030501_X2_dialog_content = "Desculpe! Eu apaguei por um momento lá.",
  str_homestory_N23dianying_90030501_X3_dialog_content = "O que você disse?",
  str_homestory_N23dianying_90030501_S1_dialog_content = "Sr. Minos? Você está bem?",
  str_homestory_N23dianying_90030501_S2_dialog_content = "Oh, me desculpe.",
  str_homestory_N23dianying_90030501_S3_dialog_content = "Você pode repetir a pergunta novamente?",
  str_homestory_N23dianying_90030501_S4_dialog_content = "Está bem. Você parece exausto...",
  str_homestory_N23dianying_90030501_S5_dialog_content = "O que eu queria perguntar é... Da última vez, você disse que se arrependeu de ter feito este filme.",
  str_homestory_N23dianying_90030501_4_dialog_content = "Claro. O que eu queria perguntar é...",
  str_homestory_N23dianying_90030501_5_dialog_content = "Da última vez, você disse que se arrependeu de ter feito este filme.",
  str_homestory_N23dianying_90030501_6_dialog_content = "Por quê?",
  str_homestory_N23dianying_90030501_X4_dialog_content = "E-É porque percebemos até o lançamento que...",
  str_homestory_N23dianying_90030501_X5_dialog_content = "Este filme pode ser amaldiçoado.",
  str_homestory_N23dianying_90030501_S6_dialog_content = "Mesmo que eu não esteja defendendo esse tipo de superstição, pessoalmente...",
  str_homestory_N23dianying_90030501_S7_dialog_content = "Mas a equipe, todos dizem que este filme é amaldiçoado.",
  str_homestory_N23dianying_90030501_7_dialog_content = "Porque... foi só quando foi lançado que percebemos...",
  str_homestory_N23dianying_90030501_8_dialog_content = "Este filme pode ser amaldiçoado.",
  str_homestory_N23dianying_90030501_9_dialog_content = "Amaldiçoado?",
  str_homestory_N23dianying_90030501_10_dialog_content = "Sim. Todo mundo que viu o filme ou participou de sua produção...",
  str_homestory_N23dianying_90030501_11_dialog_content = "Todos experimentaram coisas \"estranhas\".",
  str_homestory_N23dianying_90030501_12_dialog_content = "Olá pessoal. Hoje, estou aqui para levá-lo para dentro da Casa Assombrada Andersen!",
  str_homestory_N23dianying_90030501_13_dialog_content = "Foi originalmente propriedade de Lady Astor.",
  str_homestory_N23dianying_90030501_14_dialog_content = "Ela gritava quando as velas se apagavam.",
  str_homestory_N23dianying_90030501_15_dialog_content = "Eventualmente, ela morreu em um incêndio.",
  str_homestory_N23dianying_90030501_16_dialog_content = "O estilo do antigo proprietário era... realmente único.",
  str_homestory_N23dianying_90030501_17_dialog_content = "São apenas esses fantoches. Eles são meio esquisitos de se olhar.",
  str_homestory_N23dianying_90030501_18_dialog_content = "<color=#e8d9bb>*Caixa de música de corda soando*</color>",
  str_homestory_N23dianying_90030501_19_dialog_content = "\"Um pequeno, dois pequenos, três fantoches ♪\"",
  str_homestory_N23dianying_90030501_20_dialog_content = "A-Ahhhhhh!!!! Está de volta!",
  str_homestory_N23dianying_90030501_X20_dialog_content = "Eu tenho ouvido aquela mulher cantando essa música todas as noites desde aquele dia!",
  str_homestory_N23dianying_90030501_X21_dialog_content = "E notei que a voz dela parece estar cada vez mais perto de mim!",
  str_homestory_N23dianying_90030501_X22_dialog_content = "Meus colegas atores têm me dito a mesma coisa.",
  str_homestory_N23dianying_90030501_S20_dialog_content = "Alguns atores e funcionários a ouvem cantando todas as noites desde então.",
  str_homestory_N23dianying_90030501_S21_dialog_content = "Mas eu pessoalmente não ouvi nada.",
  str_homestory_N23dianying_90030501_S22_dialog_content = "Será que eles estão muito cansados ou alucinando?",
  str_homestory_N23dianying_90030501_21_dialog_content = "Eu tenho ouvido aquela mulher cantando essa música todas as noites desde aquele dia!",
  str_homestory_N23dianying_90030501_22_dialog_content = "E notei que a voz dela parece estar cada vez mais perto de mim!",
  str_homestory_N23dianying_90030501_23_dialog_content = "Será que você está muito cansado ou alucinando?",
  str_homestory_N23dianying_90030501_24_dialog_content = "Eu também assisti o filme antes desta entrevista.",
  str_homestory_N23dianying_90030501_25_dialog_content = "Nada está acontecendo comigo.",
  str_homestory_N23dianying_90030501_26_dialog_content = "Poderia ser apenas uma coincidência...?",
  str_homestory_N23dianying_90030501_27_dialog_content = "<color=#e8d9bb>*Passos se aproximando*</color>",
  str_homestory_N23dianying_90030501_X27_dialog_content = "Que som é esse?",
  str_homestory_N23dianying_90030501_S27_dialog_content = "O-o que é esse som?",
  str_homestory_N23dianying_90030501_S28_dialog_content = "O vento deve ter derrubado alguma coisa...",
  str_homestory_N23dianying_90030501_28_dialog_content = "O-o que foi isso...?",
  str_homestory_N23dianying_90030501_29_dialog_content = "Eu não sei. Algo parece ter sido derrubado.",
  str_homestory_N23dianying_90030501_30_dialog_content = "\"Um pequeno, dois pequenos, três fantoches ♪\"",
  str_homestory_N23dianying_90030501_S30_dialog_content = "A-Ahhhhhh!!!! T-Essa é a música!",
  str_homestory_N23dianying_90030501_S31_dialog_content = "Bom...",
  str_homestory_N23dianying_90030501_31_dialog_content = "Ahhhhhh! Essa é a música!",
  str_homestory_N23dianying_90030501_X31_dialog_content = "Uau! É isso! Essa é a música!",
  str_homestory_N23dianying_90030501_32_dialog_content = "\"Quatro pequenos, cinco pequenos, seis bonequinhos♪\"",
  str_homestory_N23dianying_90030501_S32_dialog_content = "O-o que está acontecendo?",
  str_homestory_N23dianying_90030501_S33_dialog_content = "Não entremos em pânico. Fique calmo",
  str_homestory_N23dianying_90030501_33_dialog_content = "O-o que está acontecendo?",
  str_homestory_N23dianying_90030501_34_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  str_homestory_N23dianying_90030501_35_dialog_content = "T-A luz acabou de se apagar!",
  str_homestory_N23dianying_90030501_36_dialog_content = "\"Sete pequenos, oito pequenos, nove fantoches♪\"",
  str_homestory_N23dianying_90030501_X36_dialog_content = "Oh não. É tudo culpa minha por fazer este filme...",
  str_homestory_N23dianying_90030501_S36_dialog_content = "Você, onde está o interruptor principal para as luzes? Diga-me agora!",
  str_homestory_N23dianying_90030501_37_dialog_content = "É tudo por causa desse filme... Deve ter sido amaldiçoado...",
  str_homestory_N23dianying_90030501_38_dialog_content = "\"Nove fantoches—com apenas oito cabecinhas♪\"",
  str_homestory_N23dianying_90030501_39_dialog_content = "Heheh... Você tem coragem de ver?",
  str_homestory_N23dianying_90030601_1_dialog_content = "Senhorita Siobhan, os preparativos para a operação especial estão completos. Podemos agir a qualquer momento.",
  str_homestory_N23dianying_90030601_2_dialog_content = "Obrigada! Agora estamos apenas esperando o Grande Marechal fazer o ensaio interno do anúncio de recrutamento juntos...",
  str_homestory_N23dianying_90030601_X1_dialog_content = "Comandante Vivian, os preparativos para a operação especial estão completos. Podemos agir a qualquer momento.",
  str_homestory_N23dianying_90030601_X2_dialog_content = "Bom trabalho. O Grande Marechal deve estar aqui a qualquer hora. Começaremos o ensaio interno do anúncio de recrutamento imediatamente depois disso.",
  str_homestory_N23dianying_90030601_S1_dialog_content = "Comandante Barton, os preparativos para a operação especial estão completos. Podemos agir a qualquer momento.",
  str_homestory_N23dianying_90030601_S2_dialog_content = "Bom trabalho. O Grande Marechal estará aqui a qualquer hora. Começaremos o ensaio interno do anúncio de recrutamento imediatamente depois disso.",
